output:
.saved {
  display: inline-block;
  margin-inline-start: 0.5em;
  font-size: 0.875em;
}

@media (prefers-reduced-motion: no-preference) {
  .saved {
    animation: saved-enter 180ms ease-out both;
  }

  @keyframes saved-enter {
    from {
      opacity: 0;
      transform: translateY(3px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
